F["Dockerfile"] = "FROM python:3.11-slim\n\nWORKDIR /app\n\nRUN apt-get update && apt-get install -y --no-install-recommends gcc libpq-dev curl && rm -rf /var/lib/apt/lists/*\n\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\n\nCOPY . .\n\nRUN mkdir -p data/uploads\n\nEXPOSE 8000\nCMD [\"gunicorn\", \"-k\", \"geventwebsocket.gunicorn.workers.GeventWebSocketWorker\", \"-w\", \"2\", \"-b\", \"0.0.0.0:8000\", \"--timeout\", \"120\", \"--access-logfile\", \"-\", \"run:app\"]\n"

F["docker-compose.yml"] = "version: \"3.9\"\n\nservices:\n  postgres:\n    image: postgres:16-alpine\n    container_name: capture-postgres\n    environment:\n      POSTGRES_USER: ${POSTGRES_USER}\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}\n      POSTGRES_DB: ${POSTGRES_DB}\n    volumes:\n      - pg_data:/var/lib/postgresql/data\n    restart: unless-stopped\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U ${POSTGRES_USER}\"]\n      interval: 5s\n      retries: 10\n\n  redis:\n    image: redis:7-alpine\n    container_name: capture-redis\n    command: redis-server --appendonly yes\n    volumes:\n      - redis_data:/data\n    restart: unless-stopped\n    healthcheck:\n      test: [\"CMD\", \"redis-cli\", \"ping\"]\n      interval: 5s\n      retries: 10\n\n  app:\n    build: .\n    container_name: capture-app\n    env_file: .env\n    environment:\n      - FLASK_ENV=production\n    volumes:\n      - ./data:/app/data\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n    restart: unless-stopped\n    expose:\n      - \"8000\"\n\n  worker:\n    build: .\n    container_name: capture-worker\n    command: python worker.py\n    env_file: .env\n    volumes:\n      - ./data:/app/data\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n    restart: unless-stopped\n\n  nginx:\n    image: nginx:1.27-alpine\n    container_name: capture-nginx\n    ports:\n      - \"80:80\"\n      - \"443:443\"\n    volumes:\n      - ./nginx/nginx.conf:/etc/nginx/nginx.conf:ro\n      - ./nginx/conf.d:/etc/nginx/conf.d:ro\n      - ./data/certs:/etc/nginx/certs:ro\n    depends_on:\n      - app\n    restart: unless-stopped\n\nvolumes:\n  pg_data:\n  redis_data:\n"

F["Makefile"] = "up:\n\tdocker compose up -d --build\n\ndown:\n\tdocker compose down\n\nlogs:\n\tdocker compose logs -f app worker nginx\n\nrestart:\n\tdocker compose restart app worker\n\nshell:\n\tdocker compose exec app bash\n\npsql:\n\tdocker compose exec postgres psql -U $${POSTGRES_USER} $${POSTGRES_DB}\n\nclean:\n\tdocker compose down -v\n\trm -rf data/uploads/*\n\n.PHONY: up down logs restart shell psql clean\n"

